head.script:
scwin.draw = function() {
    var options = {
        "ayaxisname": "Revenue",
        "axaxisName": "Year"
    };
    chart_test_flash.setChartAttribute(options);
    chart_test_flash.setJSONData(dataObj);
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 3. 3번샘플 실행 후 동일하게 요소검사를 통해 "accessibility_chart_test_flash"를 검색한다.
    //3. After executing sample 3, search for "accessibility_chart_test_flash" through the same element check.
    //Verify <li>Year : Jul, Revenue : 150000</li>
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('accessibility_'+$p.id+'chart_test_flash').childNodes[0].innerText == 'Year : Jul, Revenue : 150000'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('accessibility_'+$p.id+'chart_test_flash').getElementsByTagName ('tbody')[0].childNodes[0].childNodes[0].innerText == 'Jul'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('accessibility_'+$p.id+'chart_test_flash').getElementsByTagName ('tbody')[0].childNodes[0].childNodes[1].innerText == '150000'", "true");

    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('accessibility_'+$p.id+'chart_test_flash').childNodes[0].tagName == 'LI'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('accessibility_'+$p.id+'chart_test_flash').getElementsByTagName ('tbody')[0].childNodes[0].tagName == 'TR'", "true");
    WebSquare.wUnit.addCommand("pause", "2000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.dataObj = {
        "chart": {
            "yaxisname": "Revenue",
            "xaxisname": "Year"
        },
        "data": [{
                "label": "Jul",
                "value": "150000"
            },
            {
                "label": "Aug",
                "value": "130000"
            },
            {
                "label": "Sep",
                "value": "95000"
            },
            {
                "label": "Oct",
                "value": "170000"
            },
            {
                "label": "Nov",
                "value": "155000"
            },
            {
                "label": "Dec",
                "value": "230000"
            }
        ]
    };
    scwin.draw();
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 06-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
